<script setup lang="ts">
import { computed } from 'vue'
import { useUiStore } from '../../stores/ui.store'
import { useRadioStore } from '../../stores/radio.store'
import { useRadioSchedulesStore } from '../../stores/radioSchedules.store'
import IstanteIcon from '../IstanteIcon.vue'
const ui=useUiStore(),radio=useRadioStore(),schedules=useRadioSchedulesStore();const stationId=computed({get:()=>radio.currentId||radio.stations.find(s=>s.id==='chillhop')?.id||radio.stations[0]?.id||'',set:(id:string)=>{const s=radio.stations.find(x=>x.id===id);if(s)void radio.play(s)}});const programText=computed(()=>{if(!schedules.next)return'';const st=radio.stations.find(x=>x.id===schedules.next?.s.stationId);return `Prossimo avvio ${schedules.next.date.toLocaleString('it-IT',{weekday:'short',hour:'2-digit',minute:'2-digit'})}${st?` · ${st.name}`:''}`})
async function toggle(){if(!radio.current){const s=radio.stations.find(x=>x.id===stationId.value);if(s)await radio.play(s)}else radio.toggle()}async function favorite(){if(radio.current)await radio.toggleFavorite(radio.current)}
function setVolumeFromEvent(event:Event){const input=event.target as HTMLInputElement;radio.setVolume(Number(input.value)/100)}
</script>
<template><Teleport to="body"><div v-if="ui.radioOpen" class="radio-backdrop" @click.self="ui.radioOpen=false"><aside class="radio-panel" role="dialog" aria-label="Controlli radio"><header class="radio-panel-head"><IstanteIcon name="headphones" :size="22"/><div><span class="section-label">Una colonna sonora, leggera.</span><h2>Il tuo suono.</h2></div><button class="icon-button close" aria-label="Chiudi controlli radio" @click="ui.radioOpen=false"><IstanteIcon name="close"/></button></header><div class="audio-source-switch" role="group" aria-label="Sorgente audio"><button aria-pressed="true"><IstanteIcon name="headphones" :size="15"/>Radio</button><button aria-pressed="false"><IstanteIcon name="cloud" :size="15"/>Ambiente</button><button aria-pressed="false"><span class="music-note">♪</span>Melodie</button></div><div class="radio-controls"><label class="stacked-label">Stazione<select v-model="stationId"><option v-for="(s,i) in radio.stations.filter(s=>s.enabled)" :key="s.id" :value="s.id">{{String(i+1).padStart(2,'0')}}&nbsp;&nbsp;{{s.name}}</option></select></label><div class="radio-actions"><button class="text-button" @click="radio.surprise"><IstanteIcon name="shuffle" :size="16"/>Sorprendimi</button><button class="icon-button" :class="{active:radio.current?.favorite}" aria-label="Aggiungi stazione ai preferiti" @click="favorite"><IstanteIcon name="heart" :filled="radio.current?.favorite"/></button><button class="main-play" :aria-label="radio.playing?'Pausa':'Play'" @click="toggle"><IstanteIcon :name="radio.playing?'pause':'play'" :size="18"/></button></div><div class="radio-volume"><button class="icon-button" aria-label="Volume"><IstanteIcon name="volume" :size="18"/></button><input :value="radio.volume*100" aria-label="Volume radio" type="range" min="0" max="100" step="1" @input="setVolumeFromEvent"/><output>{{Math.round(radio.volume*100)}}%</output></div><p v-if="radio.error" class="field-note error">{{radio.error}}</p><div class="radio-source"><a v-if="radio.current?.website" :href="radio.current.website" target="_blank" rel="noopener">Sito della stazione <IstanteIcon name="open" :size="12"/></a><span>{{radio.playing?'Live · ':''}}{{radio.current?.provider||'FluxFM'}}</span></div><div v-if="programText" class="radio-program-info"><IstanteIcon name="clock" :size="14"/><span>{{programText}}</span></div></div></aside></div></Teleport></template>
