lor:var(--ink)}.radio-actions .main-play{margin-left:auto;width:38px;height:38px;border:1px solid var(--line);border-radius:50%;display:grid;place-items:center;background:var(--accent-soft);color:var(--accent)}.radio-volume{display:grid;grid-template-columns:36px 1fr 38px;align-items:center;gap:8px;margin-top:10px}.radio-volume input{width:100%;accent-color:var(--accent)}.radio-volume output{font-size:10px;color:var(--muted);text-align:right}.field-note{font-size:10px;line-height:1.5;color:var(--muted)}.error{color:var(--warning);margin-top:7px}.radio-source{display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid var(--line);margin-top:12px;padding-top:12px;font-size:9.5px;color:var(--muted)}.radio-source a{display:flex;align-items:center;gap:5px}.radio-source a:hover{color:var(--ink)}.radio-program-info{display:grid;grid-template-columns:auto 1fr;gap:8px;align-items:start;margin-top:14px;padding-top:13px;border-top:1px solid var(--line);color:var(--muted);font-size:9.5px;line-height:1.4}.radio-program-info>svg{color:var(--accent);margin-top:1px}@keyframes panel-in{from{opacity:0;transform:translateY(-6px) scale(.985)}to{opacity:1;transform:none}}@media(max-width:740px){.radio-backdrop{pointer-events:auto;background:rgba(6,10,7,.45);backdrop-filter:blur(5px)}.radio-panel{position:absolute;left:8px;right:8px;top:auto;bottom:max(8px,var(--safe-bottom));width:auto;max-height:calc(100dvh - 20px);border-radius:20px;padding:19px 20px}.radio-panel-head h2{font-size:27px}}
